"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[57113],{35187(e,n,t){t.r(n),t.d(n,{assets:()=>o,contentTitle:()=>l,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"scolarite/cpbx/s4/projet/synthese-culturelle","title":"Synth\xe8se culturelle","description":"Synth\xe8se culturelle du 14 mars 2019 : imaginaire collectif et interfaces cerveau-machine, fronti\xe8re entre r\xe9habilitation et augmentation, loyaut\xe9, responsabilit\xe9 et protection des individus.","source":"@site/docs/scolarite/cpbx/s4/projet/synthese-culturelle.md","sourceDirName":"scolarite/cpbx/s4/projet","slug":"/scolarite/cpbx/s4/projet/synthese-culturelle","permalink":"/docs/scolarite/cpbx/s4/projet/synthese-culturelle","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1792955287000,"sidebarPosition":4,"frontMatter":{"title":"Synth\xe8se culturelle","description":"Synth\xe8se culturelle du 14 mars 2019 : imaginaire collectif et interfaces cerveau-machine, fronti\xe8re entre r\xe9habilitation et augmentation, loyaut\xe9, responsabilit\xe9 et protection des individus.","sidebar_position":4},"sidebar":"tutorialSidebar","previous":{"title":"Avant-synth\xe8se","permalink":"/docs/scolarite/cpbx/s4/projet/avant-synthese"},"next":{"title":"M\xe9moire : r\xe9sum\xe9 et introduction","permalink":"/docs/scolarite/cpbx/s4/projet/memoire"}}');var s=t(74848),a=t(28453);const r={title:"Synth\xe8se culturelle",description:"Synth\xe8se culturelle du 14 mars 2019 : imaginaire collectif et interfaces cerveau-machine, fronti\xe8re entre r\xe9habilitation et augmentation, loyaut\xe9, responsabilit\xe9 et protection des individus.",sidebar_position:4},l=void 0,o={},u=[];function c(e){const n={blockquote:"blockquote",em:"em",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"L'utilisation du B.C.I dans la communication \xe9crite."})," Synth\xe8se culturelle r\xe9dig\xe9e par DELPEUCH S\xe9bastien, ESCOBOSA Valentin et JAVERZAT Natacha, 14 mars 2019."]}),"\n",(0,s.jsx)(n.p,{children:"Les interfaces cerveau-machine ne sont pas un concept r\xe9cent ; d\xe8s les pr\xe9mices de l'informatique, en 1945, les sc\xe9naristes et auteurs de science-fiction s'en sont empar\xe9s. Il faudra cependant attendre les ann\xe9es 1970 pour que les premiers mod\xe8les soient effectivement cr\xe9\xe9s, et vingt ann\xe9es de plus pour que les chercheurs, forts des progr\xe8s en neurosciences, mettent au point tout un panel d'interfaces utilisant diverses ondes c\xe9r\xe9brales afin de contr\xf4ler des dispositifs externes."}),"\n",(0,s.jsx)(n.p,{children:"L'acc\xe9l\xe9ration des recherches \xe0 partir des ann\xe9es 1990 ainsi que l'\xe9largissement significatif de leur champ d'application semblent indiquer que les interfaces cerveau-machine joueront un r\xf4le important dans un avenir proche. Ce constat entra\xeene l'apparition de nombreux questionnements et d\xe9bats :"}),"\n",(0,s.jsx)(n.p,{children:"Quel sera leur impact dans la vie quotidienne ? De mani\xe8re plus g\xe9n\xe9rale, quel r\xf4le, quelle place pour les interfaces cerveau-machine dans des soci\xe9t\xe9s futures ?"}),"\n",(0,s.jsx)(n.p,{children:"Si ces interrogations s'accompagnent g\xe9n\xe9ralement d'enthousiasme, d'espoirs et de fantasmes, elles peuvent \xe9galement devenir sources d'inqui\xe9tudes. Afin de g\xe9rer les attentes ainsi que les peurs autour des interfaces cerveau-machine, il semble l\xe9gitime de se poser la question suivante :"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"En quoi une future d\xe9mocratisation des interfaces cerveau-machine implique-t-elle la mise en place de mesures pr\xe9ventives ?"})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Comment anticiper d'un point de vue juridique, moral et \xe9thique de potentielles d\xe9rives ?"})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Nous \xe9tudierons ces probl\xe9matiques en nous basant sur les documents suivants :"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["Un entretien avec Nathana\xebl Jarrass\xe9 (chercheur \xe0 l'Institut des Syst\xe8mes Intelligents et de Robotique) intitul\xe9 ",(0,s.jsx)(n.em,{children:'La robotique et le mythe de "l\'Homme augment\xe9"'}),", par Franck Damour et Nathalie Sarthou-Lajus, paru dans la revue ",(0,s.jsx)(n.em,{children:"\xc9tudes"})," en f\xe9vrier 2018."]}),"\n",(0,s.jsxs)(n.li,{children:["Un extrait du livre ",(0,s.jsx)(n.em,{children:"Les robots font-ils l'amour ? Le transhumanisme en 12 questions"}),", 2016, co\xe9crit par Laurent Alexandre (m\xe9decin et entrepreneur) et Jean-Michel Besnier (philosophe sp\xe9cialiste des nouvelles technologies)."]}),"\n",(0,s.jsxs)(n.li,{children:["L'article intitul\xe9 ",(0,s.jsx)(n.em,{children:"La Libert\xe9 \xe0 l'\xe8re du num\xe9rique"}),", publi\xe9 dans la revue ",(0,s.jsx)(n.em,{children:"Politeia"})," en 2017, \xe9crit par Fran\xe7ois Pellegrini (professeur \xe0 l'Universit\xe9 de Bordeaux, chercheur impliqu\xe9 dans la Commission nationale de l'informatique et des libert\xe9s (CNIL))."]}),"\n",(0,s.jsxs)(n.li,{children:["Un extrait de la th\xe8se ",(0,s.jsx)(n.em,{children:"Coadaptation cerveau machine pour une interaction optimale : application au P300-Speller"}),", r\xe9alis\xe9e en 2012 \xe0 l'Universit\xe9 Claude Bernard, Lyon, par Margaux Perrin."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Afin de mener notre r\xe9flexion, nous \xe9tudierons d'abord l'impact de l'opinion publique vis-\xe0-vis des interfaces cerveau-machine, l'influence de la science-fiction ainsi que la n\xe9cessit\xe9 de r\xe9guler l'imaginaire collectif. Ensuite, nous nous pencherons sur la fronti\xe8re entre r\xe9habilitation et am\xe9lioration : sa nature, les enjeux \xe9thiques et juridiques soulev\xe9s. Enfin, nous nous interrogerons sur la \"loyaut\xe9 des interfaces cerveau-machine\", en soulevant notamment la question de la responsabilit\xe9 et de la protection des individus."}),"\n",(0,s.jsx)(n.p,{children:"La commercialisation et la d\xe9mocratisation des interfaces cerveau-machine sont encore lointaines, celles-ci \xe9tant pour le moment utilis\xe9es majoritairement en laboratoire, de fa\xe7on exclusivement exp\xe9rimentale. Paradoxalement, l'espoir et les fantasmes suscit\xe9s, notamment chez les malades, sont immenses. Il appara\xeet alors n\xe9cessaire de g\xe9rer cette attente, de contenir un imaginaire collectif dispos\xe9 \xe0 s'en remettre \xe0 ce qui n'est encore que science-fiction."}),"\n",(0,s.jsx)(n.p,{children:"Le d\xe9veloppement des interfaces cerveau-machine rend possible l'introduction dans la r\xe9alit\xe9 d'\xe9l\xe9ments qui relevaient jusqu'alors de la science-fiction. L'impact de ces \xe9l\xe9ments sur la population n'est pas anodin. Ainsi le \"Mythe du Cyborg\", \xe9voqu\xe9 par N. Jarrass\xe9 (document 1) et M. Perrin (document 4), peut modifier, voire biaiser la vision que l'on a du handicap. De m\xeame, l'arriv\xe9e dans les tribunaux indiens d'un \"d\xe9tecteur de mensonge\" inqui\xe8te M. Perrin, qui doute de la fiabilit\xe9 de l'appareil. On observe une opposition farouche entre technophobes et technophiles. Ces d\xe9bats, souvent st\xe9riles d'apr\xe8s N. Jarrass\xe9, font \xe9tat d'autant de craintes que de fantasmes, notamment de la part des transhumanistes (document 2). Mais, du point de vue de N. Jarrass\xe9 et M. Perrin, ces perceptions sont pour la plupart erron\xe9es. Le rapport de plus en plus \xe9troit entre science-fiction et r\xe9alit\xe9 entra\xeene de fausses id\xe9es, notamment sur le plan m\xe9dical."}),"\n",(0,s.jsx)(n.p,{children:"En effet, si de r\xe9elles alternatives m\xe9dicales semblent possibles gr\xe2ce aux interfaces homme-machine, le contraste entre imaginaire collectif et r\xe9alit\xe9 reste marqu\xe9. L'exemple de l'implant r\xe9tinien trait\xe9 par le document 1 et le document 2, ainsi que l'utilisation d'une interface cerveau-machine pour recueillir le consentement de personnes ne pouvant plus communiquer (document 4), donnent de l'espoir aux patients les plus diminu\xe9s. Cependant, ces alternatives sont pour la plupart lointaines. On observe une opposition entre la r\xe9action de N. Jarrass\xe9 (document 1) et celle de L. Alexandre (document 2) face \xe0 ce constat. Tandis que N. Jarrass\xe9 fait \xe9tat de la petitesse de nos connaissances actuelles en robotique m\xe9dicale par rapport \xe0 tout ce qu'il reste \xe0 d\xe9couvrir, L. Alexandre affiche une confiance et un enthousiasme certains."}),"\n",(0,s.jsx)(n.p,{children:"C'est ce m\xeame engouement qui fait loi chez les investisseurs. Essentiels pour l'avanc\xe9e des recherches en robotique, les investisseurs sont attir\xe9s par une demande croissante de la population. Ils sont donc influenc\xe9s par l'imaginaire collectif (document 1). Mais pas seulement : d'apr\xe8s L. Alexandre et J.M. Besnier (document 2), ils sont \xe9galement sensibles au mouvement du transhumanisme, influent jusque dans la Silicon Valley. L'innovation devient un march\xe9. Cela appara\xeet regrettable, voire dangereux, pour J.M. Besnier, inquiet quant \xe0 la strat\xe9gie des industriels, plus soucieux de produire que de respecter l'\xe9thique. \xc0 ce propos, N. Jarrass\xe9 souligne le paradoxe entre la volont\xe9 d'investissement et la non-rentabilit\xe9 des recherches actuelles, qui ne visent pas \xe0 satisfaire un \"c\u0153ur de cible\" important mais \xe0 am\xe9liorer le quotidien de quelques patients souffrant de conditions rares."}),"\n",(0,s.jsx)(n.p,{children:"Ainsi, il appara\xeet n\xe9cessaire d'anticiper au niveau social la d\xe9mocratisation des interfaces cerveau-machine. Ceci implique d'une part la lutte contre des lobbys peu scrupuleux, qui, sous couvert de b\xe9n\xe9fices, passeraient outre l'\xe9thique et la morale. D'autre part, cela suppose une \xe9ducation de la population, un recentrage sur la r\xe9alit\xe9, afin de bannir les id\xe9es fausses, les craintes ou les espoirs infond\xe9s."}),"\n",(0,s.jsx)(n.p,{children:"Cependant, ces mesures ne semblent pas \xe9videntes \xe0 mettre en place. En effet, une grande partie de la population, et notamment les investisseurs, \xe0 l'image des grandes start-ups am\xe9ricaines, attendent du futur une promesse de confort, d'augmentation de l'esp\xe9rance de vie et de r\xe9silience. Cette promesse d'am\xe9lioration s'appuie essentiellement sur les r\xe9cents progr\xe8s de la m\xe9decine, qui permettent parfois une r\xe9habilitation exceptionnelle des capacit\xe9s de personnes diminu\xe9es. Se pose alors la question de la limite entre r\xe9habilitation et am\xe9lioration. Quelle est sa nature ? Quels sont les enjeux \xe9thiques et juridiques soulev\xe9s par l'am\xe9lioration ?"}),"\n",(0,s.jsx)(n.p,{children:"L'\xe9volution de la m\xe9decine semble indiquer que la fronti\xe8re entre r\xe9habilitation et augmentation des capacit\xe9s est de plus en plus t\xe9nue. L. Alexandre soutient que la limite entre m\xe9decine r\xe9paratrice et augmentation perdra en nettet\xe9 au fil des ann\xe9es, jusqu'\xe0 ce que r\xe9habilitation et augmentation se confondent. Mais pour N. Jarrass\xe9, l'augmentation reste un mythe, car l'am\xe9lioration de certaines performances se fait toujours au d\xe9triment de la polyvalence. On remarque que les deux visions ne s'inscrivent pas dans la m\xeame temporalit\xe9 : L. Alexandre semble se projeter dans un futur plus lointain et incertain, tandis que N. Jarrass\xe9 se base sur les recherches actuelles pour appuyer un propos ancr\xe9 dans le pr\xe9sent."}),"\n",(0,s.jsxs)(n.p,{children:["Si la d\xe9finition exacte de l'augmentation et sa diff\xe9renciation avec la r\xe9habilitation sont sujettes \xe0 d\xe9bat, c'est en grande partie en raison de l'ampleur des enjeux \xe9thiques soulev\xe9s. En effet, l'augmentation suppose de possibles atteintes \xe0 l'int\xe9grit\xe9 de l'individu, non seulement physiques mais aussi morales. M. Perrin (document 4) explique que l'utilisation de neuroproth\xe8ses chez les malentendants peut \xeatre mal per\xe7ue par la communaut\xe9 sourde, qui interpr\xe8te cette application clinique comme une pression sociale, une obligation \xe0 rentrer dans la norme. De la m\xeame fa\xe7on, l'am\xe9lioration pourrait entra\xeener l'apparition d'un \"diktat de la normalit\xe9\". On peut \xe9galement soulever la question de la libert\xe9 de l'individu : en usant d'interfaces cerveau-machine toujours plus perfectionn\xe9es et toujours plus autonomes, comment l'augmentation pourrait-elle garantir la libert\xe9 individuelle ? En ce sens, F. Pellegrini (document 3) fait le constat d'une perte de libert\xe9 de l'usager de syst\xe8mes autonomes, qui renonce \xe0 la libert\xe9 de choix. Enfin, l'aspect id\xe9ologique de l'augmentation est \xe0 prendre en compte. En effet, d'apr\xe8s N. Jarrass\xe9, les fantasmes suscit\xe9s par l'image de l'humain augment\xe9 sont syst\xe9matiquement d\xe9tourn\xe9s, utilis\xe9s en politique pour servir les int\xe9r\xeats de groupes manipulateurs et dangereux. De m\xeame, le document 2 fait r\xe9f\xe9rence au ",(0,s.jsx)(n.em,{children:"Meilleur des mondes"})," de A. Huxley, ce qui sous-entend de possibles d\xe9rives discriminatoires et extr\xe9mistes."]}),"\n",(0,s.jsx)(n.p,{children:"M. Perrin (document 4) et N. Jarrass\xe9 (document 1) soulignent l'importance d'une l\xe9gislation de l'augmentation. Une base juridique est d\xe9j\xe0 en place ; N. Jarrass\xe9 consid\xe8re de grands principes et projets de lois concernant la m\xe9decine et l'informatique comme r\xe9f\xe9rences pour les chercheurs actuels. M. Perrin cite la d\xe9claration d'Helsinki, qui pose une l\xe9gislation sur le rapport b\xe9n\xe9fice/risque d'une intervention m\xe9dicale, ce qui serait applicable pour l'am\xe9lioration. De m\xeame, F. Pellegrini juge primordial de conserver les droits fondamentaux et la l\xe9gislation existante concernant la protection de l'individu et la loyaut\xe9 des traitements algorithmiques. Cependant, N. Jarrass\xe9 et F. Pellegrini soulignent un besoin de renforcement, de mise \xe0 jour des comit\xe9s d'\xe9thique et de la l\xe9gislation, qui ne sont pas toujours adapt\xe9s pour r\xe9pondre \xe0 l'\xe9volution rapide des technologies."}),"\n",(0,s.jsx)(n.p,{children:"Ainsi, les enjeux \xe9thiques, individuels et collectifs, autour de l'am\xe9lioration concernent notamment les droits fondamentaux des individus, le respect de l'int\xe9grit\xe9, la lutte contre les extr\xeames. L'anticipation de d\xe9rives telles que l'apparition de pressions sociales ou de discriminations, par la cr\xe9ation d'un cadre juridique strict, appara\xeet essentielle."}),"\n",(0,s.jsx)(n.p,{children:"De mani\xe8re plus g\xe9n\xe9rale, la l\xe9gislation des interfaces cerveau-machine semble se baser sur le principe de loyaut\xe9. Le terme \"loyaut\xe9\" implique ici la fiabilit\xe9, la transparence de ces syst\xe8mes, ainsi que la droiture, l'impartialit\xe9 et l'honn\xeatet\xe9 des concepteurs."}),"\n",(0,s.jsx)(n.p,{children:"Lorsque l'on est face \xe0 un syst\xe8me partiellement ou totalement autonome, on se pose naturellement la question de la responsabilit\xe9. La d\xe9ficience d'un tel syst\xe8me peut avoir des cons\xe9quences importantes, comme des atteintes \xe0 l'int\xe9grit\xe9 physique (document 4), mais qui est fautif ? L'utilisateur ou le concepteur ? Le probl\xe8me reste insoluble pour M. Perrin, qui souligne encore une fois la n\xe9cessit\xe9 de poser un cadre juridique strict. Pour F. Pellegrini, la question soulev\xe9e rejoint celle de la garantie de la libert\xe9 de l'utilisateur, car le fait de ne pas avoir la main sur ces syst\xe8mes constitue d\xe9j\xe0 une atteinte \xe0 notre libre arbitre. La question de la responsabilit\xe9 des interfaces cerveau-machine reste donc en suspens."}),"\n",(0,s.jsx)(n.p,{children:"Ce flou juridique et moral autour de la responsabilit\xe9 n'entrave pas l'\xe9lan des pro-technologies. L. Alexandre (document 2) vante la toute-puissance de la culture de l'innovation, s'opposant \xe0 J.M. Besnier, qui pr\xe9f\xe8re une approche plus timide des avanc\xe9es technologiques, r\xe9gl\xe9e sur la morale. N. Jarrass\xe9 (document 1) rejoint J.M. Besnier sur ce point : pour lui, il n'y a pas de technique sans \xe9thique. Cependant, il ne s'agit pas non plus de craindre la technologie. F. Pellegrini (document 3) justifie l'importance d'expliciter le sens des diff\xe9rents termes techniques employ\xe9s, car le simple abus de langage qui consiste \xe0 parler de \"loyaut\xe9 des algorithmes\" plut\xf4t que de \"loyaut\xe9 des traitements\" pose d\xe9j\xe0 probl\xe8me. En effet, un algorithme est un objet math\xe9matique abstrait, c'est un progr\xe8s technique qui ne peut constituer une menace. Par contre, la mani\xe8re dont il est trait\xe9, utilis\xe9, peut \xe9ventuellement \xeatre \xe0 l'origine de d\xe9rives. Dans la m\xeame id\xe9e, L. Alexandre et J.M. Besnier s'accordent \xe0 penser que la technique n'est pas par nature bonne ou mauvaise ; c'est l'usage qui importe. Il ne s'agit donc pas de pr\xe9f\xe9rer \xe9thique ou technique, mais plut\xf4t d'allier les deux."}),"\n",(0,s.jsx)(n.p,{children:"Si l'\xe9thique appara\xeet comme un sujet redondant lorsque l'on traite des interfaces cerveau-machine, c'est essentiellement parce que la protection de l'individu est en jeu. Entre autres, le probl\xe8me de la r\xe9gulation des donn\xe9es personnelles est avanc\xe9. F. Pellegrini mentionne la \"guerre de la biom\xe9trie\", cette collecte massive de donn\xe9es \xe0 l'\xe9chelle internationale, qui pourrait s'intensifier davantage avec la d\xe9mocratisation des interfaces cerveau-machine. M. Perrin souligne \xe9galement le probl\xe8me du consentement. Comment prendre la d\xe9cision d'implanter ou non une interface cerveau-machine lorsque le patient ne peut plus communiquer son accord ? Enfin, on peut douter de la transparence des traitements et des machines vis-\xe0-vis des usagers. Pour F. Pellegrini, le plus naturel et le plus juste serait d'informer syst\xe9matiquement l'usager de la mani\xe8re dont sont trait\xe9es les donn\xe9es recueillies. Cependant, dans le cas des algorithmes auto-apprenants (donc potentiellement des interfaces cerveau-machine), cette information devient si complexe qu'elle d\xe9passe l'utilisateur."}),"\n",(0,s.jsx)(n.p,{children:"Les interfaces cerveau-machine se doivent d'\xeatre au service de l'homme et, en ce sens, de respecter les grands principes d\xe9j\xe0 effectifs concernant la protection de l'int\xe9grit\xe9 physique et morale des individus. Il ne s'agit pas pour autant de craindre ces inventions et d'opposer syst\xe9matiquement la technique et l'\xe9thique, mais plut\xf4t de trouver un terrain d'entente. Technique et \xe9thique doivent s'\xe9couter et se compl\xe9ter, et ce afin de garantir la protection des individus."}),"\n",(0,s.jsx)(n.p,{children:"En conclusion, nous pouvons affirmer qu'il est essentiel d'anticiper d\xe8s maintenant la d\xe9mocratisation des interfaces cerveau-machine. Ces syst\xe8mes sont r\xe9cents, mal connus et largement connot\xe9s par le biais de la science-fiction. Ainsi, ils peuvent \xeatre \xe0 l'origine de confusions, de peurs ou, au contraire, susciter une attente d\xe9mesur\xe9e. Le contr\xf4le de cet imaginaire collectif est la premi\xe8re mesure pr\xe9ventive \xe0 adopter, via l'\xe9ducation de la population."}),"\n",(0,s.jsx)(n.p,{children:"Des d\xe9rives importantes sont \xe0 envisager, notamment autour de la question de l'am\xe9lioration. Pr\xe9voir ces d\xe9rives par l'instauration d'un cadre juridique et \xe9thique est primordial. De mani\xe8re plus g\xe9n\xe9rale, la d\xe9mocratisation des interfaces cerveau-machine sous-entend un besoin indispensable de l\xe9gif\xe9rer, de r\xe9gler au mieux leur fabrication et leur utilisation."})]})}function d(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>l});var i=t(96540);const s={},a=i.createContext(s);function r(e){const n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);